function commonDir(paths: string[]) {
    const parts = paths.map(p => path.posix.dirname(p).split("/"))
    const common: string[] = []
    for (let i = 0; i < parts[0].length && parts.every(p => p[i] === parts[0][i]); i++) common.push(parts[0][i])
    return common.join("/") || "/"
}

